					// ── ABS. About Us V2 — Story ──────────────────────────────────────
				// One layout, not twelve: about-v2.js placeRail() measures the direct
				// <section> children of .abs-story-track, so a single component has to
				// own that wrapper and emit the chapters inside it. A flat dispatcher
				// would make every chapter a sibling and the rail would lose its
				// reference frame.
